const datos = $json;

const usuario = String(datos.sessionId ?? "").trim();
const pregunta = String(datos.pregunta ?? "");

// Permisos ficticios para la demostración.
const permisos = {
  "cliente_prueba_01": ["Banca 01"],
  "cliente_prueba_02": ["Banca 02"]
};

// Identificar las bancas mencionadas en la consulta.
const coincidencias = [
  ...pregunta.matchAll(/\bbanca\s*0*(\d+)\b/gi)
];

const bancasSolicitadas = [
  ...new Set(coincidencias.map(m =>
    `Banca ${String(Number(m[1])).padStart(2, "0")}`
  ))
];

const bancasPermitidas = permisos[usuario] ?? [];

// Para esta prueba exigimos una banca explícita.
const autorizado =
  bancasPermitidas.length > 0 &&
  bancasSolicitadas.length === 1 &&
  bancasPermitidas.includes(bancasSolicitadas[0]);

return {
  json: {
    ...datos,
    bancaAutorizada: bancasPermitidas[0] ?? null,
    bancaSolicitada: bancasSolicitadas[0] ?? null,
    autorizado,
    mensajeError: autorizado
      ? null
      : "No tenés autorización para realizar esta consulta o falta indicar una banca válida."
  }
};

// 1) Sólo documentos con banca validada en metadatos.
const solicitud = $('If').first().json;
const banca = String(solicitud.bancaAutorizada ?? '').trim();
const normalizar = (x) => String(x ?? '').normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const pregunta = normalizar(solicitud.pregunta);
const encontrados = $input.all().map(item => item.json?.document ?? item.json ?? {});
const documentos = encontrados.filter(doc =>
  normalizar(doc.metadata?.banca) === normalizar(banca) &&
  banca !== '' && typeof doc.pageContent === 'string' && doc.pageContent.trim() !== ''
);

// 2) Separar las filas presupuestarias y conservar sus metadatos.
// Simple Vector Store puede devolver el mismo registro repetido tras varias ingestas.
// Eliminar SOLO filas idénticas; NO mezclar cuentas, rubros ni importes diferentes.
const filas = [];
const filasVistas = new Set();
let filasDuplicadasDescartadas = 0;
for (const doc of documentos) {
  const rubro = String(doc.metadata?.rubro ?? '');
  for (const linea of doc.pageContent.split(/\r?\n/)) {
    if (!/\bNombre de cuenta\s*:/i.test(linea) || !/\bDESVIO_YTD\s*:/i.test(linea)) continue;
    const nombre = (linea.match(/Nombre de cuenta:\s*(.*?)\s*\|\s*PLAN_YTD\s*:/i) ?? [])[1] ?? '';
    const cuenta = (linea.match(/\bCuenta:\s*(\d+)\b/i) ?? [])[1] ?? '';
    const lineaLimpia = linea.trim();
    const clave = [normalizar(banca), normalizar(rubro), cuenta, lineaLimpia].join('||');
    if (filasVistas.has(clave)) {
      filasDuplicadasDescartadas++;
      continue;
    }
    filasVistas.add(clave);
    filas.push({ rubro, nombre, cuenta, linea: lineaLimpia });
  }
}

// 3) Resolver la petición concreta antes de construir el contexto del modelo.
const cuentaPedida = (solicitud.pregunta.match(/\bcuenta\s*(\d{6,})\b/i) ?? [])[1];
const rubros = [...new Set(filas.map(f => f.rubro).filter(Boolean))];
const rubroPedido = rubros.find(r => pregunta.includes(normalizar(r)));
const nombresMencionados = filas.filter(f => f.nombre && pregunta.includes(normalizar(f.nombre)));
let relevantes = filas;
if (cuentaPedida) {
  relevantes = filas.filter(f => f.cuenta === cuentaPedida);
} else if (nombresMencionados.length) {
  relevantes = nombresMencionados;
} else if (rubroPedido) {
  relevantes = filas.filter(f => normalizar(f.rubro) === normalizar(rubroPedido));
}

// Preguntas de lista: nunca afirmar que se recuperó todo el universo.
const esListado = /\b(enumera|enumera|lista|listar|todas las cuentas|todos los registros)\b/.test(pregunta);
const totalRelevantes = relevantes.length;
const limiteFilas = esListado ? 3 : 6;
relevantes = relevantes.slice(0, limiteFilas);
const contextoRAG = relevantes.map(f =>
  `Banca: ${banca} | Rubro: ${f.rubro} | ${f.linea}`
).join('\n');

return [{ json: {
  ...solicitud,
  contextoRAG,
  cantidadDocumentos: documentos.length,
  documentosDescartados: encontrados.length - documentos.length,
  cantidadFilasRelevantes: totalRelevantes,
  filasDuplicadasDescartadas,
  filasEnviadasAlModelo: relevantes.length,
  listadoParcial: esListado,
} }];

// Validación determinística de consultas a cuentas y listas.
// Se ejecuta DESPUÉS del AI Agent y utiliza únicamente filas RAG
// cuya banca fue verificada en "Filtrar documentos RAG".
const entrada = $input.first()?.json ?? {};
const fuente = $('Filtrar documentos RAG').first().json;
const sinDatos = 'No encontré información suficiente para responder con los datos disponibles.';
const normalizar = v => String(v ?? '').normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const pregunta = normalizar(fuente.pregunta);
const bancaAutorizada = normalizar(fuente.bancaAutorizada);
const numeroCuenta = (String(fuente.pregunta).match(/\bcuenta\s*(\d{6,})\b/i) ?? [])[1];
const esLista = /\b(enumera|enumera|lista|listame|listar|todas las cuentas|todos los registros)\b/.test(pregunta);
const pideYtd = /\bYTD\b/i.test(fuente.pregunta);
const pideMtd = /\bMTD\b/i.test(fuente.pregunta);
const periodo = pideYtd && !pideMtd ? 'YTD' : pideMtd && !pideYtd ? 'MTD' : null;

function leerCampos(linea) {
  const valores = {};
  for (const segmento of linea.split('|')) {
    const pos = segmento.indexOf(':');
    if (pos !== -1) valores[segmento.slice(0, pos).trim()] = segmento.slice(pos+1).trim();
  }
  return valores;
}
function numeroValido(x) { return /^-?\d+(?:\.\d+)?$/.test(String(x ?? '')); }
function importe(x) { return new Intl.NumberFormat('es-AR', {maximumFractionDigits: 2}).format(Number(x)); }
function calcularValidado(f, periodo) {
  if (!periodo) return null;
  const plan = f['PLAN_' + periodo], real = f['REAL_' + periodo], desvio = f['DESVIO_' + periodo];
  if (![plan, real, desvio].every(numeroValido)) return null;
  if (Math.abs((Number(plan) - Number(real)) - Number(desvio)) > 0.000001) return null;
  return Number(desvio);
}
// Segunda defensa: no considerar ambiguas varias copias de la MISMA fila RAG.
// El Set preserva filas distintas, aun si coinciden en el nombre de cuenta.
const lineasUnicas = [...new Set(String(fuente.contextoRAG ?? '')
  .split(/\r?\n/).map(s => s.trim())
  .filter(s => /\bNombre de cuenta\s*:/i.test(s)))];
const filas = lineasUnicas.map(leerCampos)
  .filter(f => normalizar(f.Banca) === bancaAutorizada && f['Nombre de cuenta']);
let texto = entrada.text ?? entrada.output ?? entrada.response?.text ?? entrada.response?.output ?? '';
if (typeof texto !== 'string') texto = String(texto ?? '');
texto = texto.trim();
let tipoRespuesta = 'modelo';

if (fuente.autorizado !== true || !bancaAutorizada) {
  texto = sinDatos;
  tipoRespuesta = 'rechazo_seguridad';
} else if (numeroCuenta || esLista || filas.some(f => pregunta.includes(normalizar(f['Nombre de cuenta'])))) {
  let seleccion = [];
  if (numeroCuenta) {
    seleccion = filas.filter(f => f.Cuenta === numeroCuenta);
  } else if (esLista) {
    seleccion = filas.slice(0, 3);
  } else {
    seleccion = filas.filter(f => pregunta.includes(normalizar(f['Nombre de cuenta'])));
  }
  // Si no hay un período solicitado inequívocamente, no se adivina YTD/MTD.
  const valores = seleccion.map(f => ({f, valor: calcularValidado(f, periodo)}));
  if (!valores.length || valores.some(x => x.valor === null) || !periodo) {
    texto = sinDatos;
    tipoRespuesta = 'sin_datos_validados';
  } else if (esLista) {
    // Las cifras de la lista se extraen de RAG y se validan aritméticamente.
    // La IA redacta el análisis; este control corrige comparaciones numéricas erróneas.
    const muestra = valores.slice(0, 3);
    texto = `Muestra parcial de ${fuente.bancaAutorizada} (hasta 3 cuentas recuperadas):\n` +
      muestra.map((x, i) => `${i+1}. ${x.f['Nombre de cuenta']}: ${importe(x.valor)} (${x.valor < 0 ? 'sobregasto' : x.valor > 0 ? 'menor gasto' : 'sin desvío'})`).join('\n');
    const pideMayorSobregasto = /\bmayor(?:es)?\s+(?:el\s+)?sobregasto\b|\bmas\s+sobregasto\b/.test(pregunta);
    const pideExplicacion = /\bexplica|\bexplicame|\bdiferencias|\bcompara|\bcomparacion\b/.test(pregunta);
    if (pideMayorSobregasto) {
      const sobregastos = muestra.filter(x => x.valor < 0);
      if (sobregastos.length) {
        const minimo = Math.min(...sobregastos.map(x => x.valor));
        const mayores = sobregastos.filter(x => x.valor === minimo);
        const nombres = mayores.map(x => x.f['Nombre de cuenta']).join(' y ');
        texto += `\nMayor sobregasto de esta muestra: ${nombres} (${importe(minimo)}).`;
      } else {
        texto += '\nNo hay sobregastos entre las cuentas mostradas.';
      }
    }
    if (pideExplicacion) {
      texto += '\nNegativo = gasto superior al plan; positivo = menor gasto. No se dispone de causas.';
    }
    tipoRespuesta = (pideMayorSobregasto || pideExplicacion) ? 'lista_comparada_validada' : 'lista_validada';
  } else if (valores.length === 1) {
    const {f,valor} = valores[0];
    texto = `${fuente.bancaAutorizada} — ${f['Nombre de cuenta']}: desvío ${periodo} de ${importe(valor)} (${valor < 0 ? 'sobregasto' : valor > 0 ? 'menor gasto' : 'sin desvío'}).`;
    tipoRespuesta = 'cuenta_validada';
  } else {
    texto = sinDatos;
    tipoRespuesta = 'ambigua';
  }
} else if (!texto) {
  texto = sinDatos;
  tipoRespuesta = 'sin_respuesta_modelo';
}

// Límite técnico de hasta tres elementos y 600 caracteres.
let elementos = 0;
texto = texto.split('\n').filter(linea => {
  if (!/^\s*(?:[-*•]\s+|\d+[.)]\s+)/.test(linea)) return true;
  elementos++;
  return elementos <= 3;
}).join('\n').trim();
if (texto.length > 600) {
  const tramo = texto.slice(0, 597);
  const espacio = tramo.lastIndexOf(' ');
  texto = (espacio > 450 ? tramo.slice(0, espacio) : tramo).trimEnd() + '…';
}
// Un resultado insuficiente NO debe publicarse como estado funcional 'ok'.
const sinResultado = ['rechazo_seguridad', 'sin_datos_validados', 'ambigua', 'sin_respuesta_modelo'].includes(tipoRespuesta) || texto === sinDatos;
return [{json: {output: texto, estado: sinResultado ? 'sin_datos' : 'ok', verificacion: tipoRespuesta}}];
